INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 1, 0, 1.5, 110, 1, 0.029, 1, 1, 122601, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 101, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 120, 2, 1, 2.5, 105, 2, 0.014, 3, 0, 122401, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 102, 111);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 3, 0, 2.5, 110, 3, 0.017, 2, 0, 122501, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 103, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 4, 1, 1.5, 110, 4, 0.016, 3, 0, 107501, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 104, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 5, 0, 2.5, 110, 5, 0.014, 1, 1, 107601, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 105, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 255, 6, 0, 3.5, 120, 6, 0.029, 2, 0, 107801, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 106, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 7, 0, 3.5, 120, 7, 0.013, 1, 1, 110601, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 107, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 8, 0, 2.5, 110, 8, 0.014, 2, 0, 110401, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 108, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 9, 1, 1.5, 105, 9, 0.012, 3, 0, 110501, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 109, 100);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 200, 10, 0, 2.5, 105, 10, 0.014, 1, 1, 115701, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 110, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 11, 0, 2.5, 105, 11, 0.071, 2, 0, 113601, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 111, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 12, 1, 1.5, 120, 12, 0.014, 3, 0, 107901, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 112, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 200, 13, 0, 1.5, 110, 13, 0.022, 2, 1, 108001, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 113, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 14, 0, 2.5, 110, 14, 0.031, 1, 1, 110301, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 114, 108);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 15, 1, 0.5, 110, 15, 0.036, 1, 0, 107701, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 115, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 16, 0, 3.5, 110, 16, 0.048, 2, 0, 113101, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 116, 95);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 17, 1, 1.5, 105, 17, 0.043, 3, 0, 113301, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 117, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 18, 1, 1.5, 105, 18, 0.018, 2, 0, 113201, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 118, 95);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 19, 0, 2.5, 110, 19, 0.021, 2, 1, 117001, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 119, 108);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 255, 20, 0, 2.5, 110, 20, 0.036, 1, 0, 113501, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 120, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 21, 0, 2.5, 105, 21, 0.02, 3, 0, 113401, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 121, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 22, 1, 2.5, 110, 22, 0.018, 1, 0, 110101, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 122, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 23, 0, 3.5, 105, 23, 0.03, 3, 1, 110001, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 123, 111);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 24, 1, 1.5, 110, 24, 0.027, 1, 0, 117201, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 124, 103);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 160, 25, 0, 3.5, 105, 25, 0.02, 2, 1, 117301, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 125, 108);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 26, 0, 2.5, 110, 26, 0.04, 3, 0, 117401, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 126, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 350, 27, 0, 3.5, 110, 27, 0.009, 1, 0, 117101, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 127, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (1, 255, 28, 0, 3.5, 120, 28, 0.022, 1, 0, 122901, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 128, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 29, 1, 2.5, 110, 29, 0.028, 3, 0, 122801, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 129, 105);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0, 130, 30, 0, 3.5, 105, 30, 0.023, 2, 1, 122701, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 130, 108);
